class InitOrderBug {
    // 1. Declared first: initialized first (to garbage/zero)
    int first_member;

    // 2. Declared second: initialized second
    int second_member;

public:
    // Initializer list order is misleading
    InitOrderBug(int val)
        // UB: second_member uses first_member's uninitialized state
        : second_member(first_member + val),
          first_member(val)
    {
        // second_member is unpredictable
    }
};

// Rule: Members initialize in declaration order.
